    return n * n;
}

double circleArea(double r) {
    return PI * r * r;
}

int main() {
    int x;
    cout << "Enter a number: ";
    cin >> x;
    cout << "Square of " << x << " = " << square(x) << endl;

    double radius;
    cout << "Enter radius: ";
    cin >> radius;
    cout << "Area of circle = " << circleArea(radius) << endl;
    return 0;
}

#include <iostream>
using namespace std;

bool isPrime(int n);             // function prototype (declaration)

int main() {
    cout << "Prime numbers from 1 to 50:" << endl;
    int count = 0;
    for (int i = 1; i <= 50; i++) {
        if (isPrime(i)) {
            cout << i << " ";
            count++;
        }
    }
    cout << "\nTotal: " << count << endl;
    return 0;
}

bool isPrime(int n) {            // function definition after main
    if (n < 2)
        return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0)
            return false;
    return true;
}

#include <iostream>
using namespace std;

void swapByValue(int a, int b) {
    int t = a; a = b; b = t;     // swaps only the copies
}

void swapByReference(int &a, int &b) {
    int t = a; a = b; b = t;     // swaps the original variables
}

int main() {
    int x = 10, y = 20;
    swapByValue(x, y);
    cout << "After swapByValue:     x = " << x << ", y = " << y << endl;
    swapByReference(x, y);
    cout << "After swapByReference: x = " << x << ", y = " << y << endl;
    return 0;
}

#include <iostream>
using namespace std;

double interest(double p, double years, double rate = 6.5) {
    return p * rate * years / 100;
}

int main() {
    cout << "Rs 10000 for 2 years at default 6.5% = Rs "
         << interest(10000, 2) << endl;
    cout << "Rs 10000 for 2 years at 8%          = Rs "
         << interest(10000, 2, 8) << endl;
    return 0;
}

#include <iostream>
using namespace std;

double area(double side) {                  // square
    return side * side;
}

double area(double length, double width) {  // rectangle
    return length * width;
}

double area(double a, double b, double h) { // trapezium: (a + b) / 2 * h
    return (a + b) / 2 * h;
}

int main() {
    cout << "Square of side 5       : " << area(5.0) << endl;
    cout << "Rectangle 8 x 6        : " << area(8.0, 6.0) << endl;
    cout << "Trapezium 6, 10, h = 4 : " << area(6.0, 10.0, 4.0) << endl;
    return 0;
}

