#include <iostream>
using namespace std;

long long factorial(int n) {
    if (n <= 1)                  // base case
        return 1;
    return n * factorial(n - 1); // recursive case
}

int digitSum(int n) {
    if (n == 0)
        return 0;
    return n % 10 + digitSum(n / 10);
}

int main() {
    cout << "5! = " << factorial(5) << endl;
    cout << "10! = " << factorial(10) << endl;
    cout << "Sum of digits of 2026 = " << digitSum(2026) << endl;
    return 0;
}

#include <iostream>
using namespace std;

double toFahrenheit(double c) { return c * 9 / 5 + 32; }
double toCelsius(double f)    { return (f - 32) * 5 / 9; }

double kmToMiles(double km)   { return km * 0.621371; }

void showMenu() {
    cout << "\n1. Celsius to Fahrenheit\n";
    cout << "2. Fahrenheit to Celsius\n";
    cout << "3. Kilometres to miles\n";
    cout << "4. Exit\n";
    cout << "Choice: ";
}

int main() {
    int choice;
    double v;
    do {
        showMenu();
        cin >> choice;
        switch (choice) {
            case 1: cout << "Celsius: ";    cin >> v;
                    cout << "= " << toFahrenheit(v) << " F\n"; break;
            case 2: cout << "Fahrenheit: "; cin >> v;
                    cout << "= " << toCelsius(v) << " C\n"; break;
            case 3: cout << "Kilometres: "; cin >> v;
                    cout << "= " << kmToMiles(v) << " miles\n"; break;
            case 4: cout << "Goodbye!\n"; break;
            default: cout << "Invalid choice\n";
        }
    } while (choice != 4);
    return 0;
}
